INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Padmanabhaswamy Temple', 'The Padmanabhaswamy Temple (Malayalam: [pɐd̪mɐnaːbʰɐswaːmi]) is a Hindu temple dedicated to Vishnu in Thiruvananthapuram, Kerala, India. It is one of the 108 Divya Desams, sacred sites of the Sri Vaishnava tradition.
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Kovalam Beach', 'Kovalam (Malayalam: [koːʋɐɭɐm]) is a beach and seaside resort in the city of Thiruvananthapuram in Kerala, India. Kovalam is located 12.6 km (7.8 mi) southeast of the city center. The beaches around Kovalam are popular vacation destinations for both domestic and international travellers.', 'Beach', 'Kovalam Beach, Kovalam, - 695527, KL, India', 8.3950997, 76.9729934, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/3/3c/Kovalam_beach_trivandrum_kerala.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Varkala Beach', 'Varkala Beach is situated in the town of Varkala in Varkala Municipality, Thiruvananthapuram district, Kerala, India. The beach skirts the Arabian Sea, part of the Indian Ocean.', 'Beach', 'Varkala Beach, Varkala, India', 8.73322845, 76.7054244896022, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/e/e0/Varkala_beach_from_above.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Ponmudi Hill Station', '', 'Hill Station', 'Ponmudi Hill Station, Thiruvananthapuram - Ponmudi Road, Ponmudi -, KL, India', 8.7668888, 77.109477, 4.5, '', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Neyyar Dam', 'Neyyar dam is a gravity dam on the Neyyar River in Thiruvananthapuram district of Kerala, South India, located on the foot of the Western Ghats about 30 km from Thiruvananthapuram. It was established in 1958 and is a popular picnic spot.The Neyyardam was built in the land given by a famous agriculturist and landlord Mr. Karuvachi Krishnan Panicker,(Father of Kallikkad Kesavan Panicker(Father of Kallikad Ramachandran) ) Maruthummootil, Kallikkad and many of his family members from Kallikkad.', 'Dam/Lake', 'Neyyar Dam, -, KL, India', 8.535016, 77.145894, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/b/bf/Neyyar_Dam_Full_View.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Neyyar Wildlife Sanctuary', 'The Neyyar Wildlife Sanctuary in the southern state of Kerala in India is spread over the southeast corner of the Western Ghats, and covers a total area of 128 km2 (49 sq mi). It is located  between 77° 8’ to 77° 17’ east longitude and  8° 29’ to  8° 37’  north latitude, central location 8°33′N 77°12.5′E.  Although it was declared as a sanctuary in 1958, not much was done about wildlife conservation, until 1985, when a separate wildlife wing was set up and as a result, conservation efforts have ', 'Wildlife', 'Neyyar Wildlife Sanctuary, Kottoor-Kappukad Road, - 695574, KL, India', 8.5609971, 77.1727415, 4.5, '', true);
