INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Shankumugham Beach', 'Shankumugham Beach is a beach in Thiruvananthapuram district of Kerala, south India. The beach is on the western side of Thiruvananthapuram and is very close to Thiruvananthapuram International Airport.
