INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Kanakakunnu Palace', '', 'Culture/History', 'Kanakakkunnu Palace, Museum Road, Vellayambalam, Thiruvananthapuram - 695001, KL, India', 8.51065275, 76.95810021934584, 4.5, '', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Koyikkal Palace', 'The Koyikkal Palace is a palace situated in Nedumangadu, Thiruvananthapuram District, Kerala, India.  The palace was built in 17th century for Umayamma Rani of the Venad Royal Family.  Umayamma Rani was the queen of Venad between 1677 and 1684.  The palace is a double storied building and built in the traditional architectural style of Kerala.
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Agasthyarkoodam', 'Agathiyar Malai (or Agasthiyarkoodam) is one of the peaks of the Agathiyarmalai Biosphere Reserve in the Western Ghats that lies between the districts of Tirunelveli District of Tamil Nadu and Thiruvananthapuram District of Kerala, India. This peak is specifically located in the Thiruvananthapuram district of Kerala, near the Tamil Nadu border. It is 1,868-metres (6,129 ft) tall.. The perennial Thamirabarani River originates from the eastern side of the range and flows into the Tirunelveli distr', 'Tourist Attraction', 'Athirumala Agasthyarkoodam trail, -, TN, India', 8.617642, 77.248021, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/f/f4/Agasthyarkoodam.JPG', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Peppara Dam', 'Peppara Dam is a masonry gravity dam on the Karamana River in Thiruvananthapuram District. It is built by the Kerala Water Authority in 1983 has a catchment area of 83 km2 and receives an average rain fall of 481 cm. The 423m long dam unifies all upper tributaries of the Karamana river and water flow to Aruvikkara is regulated to suit the needs of the Trivandrum city. There is also a 3MW hydel power station at Peppara. It is the main drinking water supply to Thiruvananthapuram city and suburban ', 'Dam/Lake', 'Peppara Dam, -, KL, India', 8.622575, 77.138178, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/c/c6/Peppara_Dam_Reservoir_Side_View_IMG_20141003_174810.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Anchuthengu Fort', 'The fort was the East India Company''s first permanent post on the Malabar Coast. In November 1693, John Brabourne was sent by the British East India Company (EIC) to Attingal, where he obtained from Rani Ashure a grant of a site for a fort on the sandy spit of Anchuthengu (then known as Anjengo), together with the monopoly of the pepper trade of Attingal. The EIC commenced construction in January 1696.
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Vizhinjam Lighthouse', 'Vizhinjam Lighthouse or Trivandrum Lighthouse is situated near Kovalam beach in Kerala. It started functioning on 30 June 1972. Vizhinjam was a busy seaport in the eighteenth and nineteenth centuries. Before the current light was installed, there were no lighthouses at this location. A day mark beacon (flag mast) must have been there in 18th century. After 19th century, this port was in a neglected state. A lighted beacon was constructed in 1925 at nearby Kolachal. Subsequently, a day mark beaco', 'Tourist Attraction', 'Vizhinjam, KL, India', 8.383255, 77.003503, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/d/d5/Vizhinjam_Light_House.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Aruvikkara Dam', 'Aruvikkara Dam (Malayalam: അരുവിക്കര അണക്കെട്ട്) is located in Aruvikkara in Thiruvananthapuram District, Kerala. This Gravity and Masonry dam was built across the Karamana River and was completed in 1972 is used for irrigation and supplying drinking water to the city of Thiruvananthapuram. The Aruvikkara dam project came up in the 1930s and has been supported by the Peppara dam built in 1983. The height of the dam is 14.01 meters (45.96 ft) and the length is 83.21 meters (273 ft). The Aruvikkar', 'Dam/Lake', 'Aruvikkara Dam, Aruvikkara - 685541, KL, India', 8.5738062, 77.0210412, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/a/a8/Aruvikkara_Dam_%28261210689%29.jpg', true);
