INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Janardanaswamy Temple', 'The Janardanaswamy Temple, also known as the Varkala Temple, is a Hindu temple situated in Janardhanapuram, Varkala city, Thiruvananthapuram district, Kerala, India. The temple is dedicated to the worship of deity Vishnu in the form of Janardanaswamy, locally known as Varkaleswara (the lord of Varkala). It is a renowned temple within its locale, and is thousands of years old.', 'Religious Site', 'Chottanikkara Devi temple, Muriyamangalam- Chottanikkara Road, Chottanikkara, - 682312, KL, India', 9.93331615, 76.391160474779, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/8/8a/Janardhana_swamy_temple.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Sivagiri Mutt', 'Sivagiri is an area in Varkala Municipality of Thiruvananthapuram district in Kerala. It is a pilgrimage centre of Varkala Town where the tomb, or samadhi, of Sree Narayana Guru is situated. It is a place where Guru built the Sarada Temple dedicated to Sarada Devi. The tomb is an attraction for thousands of devotees every year, especially during the Sivagiri Pilgrimage days (Sivagiri Theerthadanam) from 30 December to 1 January. 
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Ashtamudi Lake', 'Ashtamudi Lake (Ashtamudi Kayal, ml: "അഷ്ടമുടിക്കായൽ" ), in the Kollam District of the Indian state of Kerala is a unique wetland ecosystem and a large palm-shaped (also described as octopus-shaped) water body. It is second only in size to the Vembanad estuary ecosystem of the state. Ashtamudi means ''eight hills or peaks'' (Ashta : ''eight''; mudi : ''peaks'') in the local Malayalam language. The name is indicative of the lake''s topography with its multiple branches. The lake is also called the gatew', 'Dam/Lake', 'Lake, Waluj MIDC, Gangapur - 431136, MH, India', 19.8420978, 75.2153177, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/f/f0/Ashtamudi_Kerala.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Kollam Beach', 'Kollam Beach, also known as Mahatma Gandhi Beach, is a beach at Kollam city in the Indian state of Kerala. Kollam Beach is the first ''Beach Wedding Destination'' in Kerala.
