INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Jatayu Earth’s Center', 'Jatayu Earth''s Center, (IPA: [dʒɐʈaːju]) also known as Jatayu Nature Park  is a national park and tourism centre at Chadayamangalam in Kollam district of Kerala, India. It stands at an altitude of 350 m (1,150 ft) above mean sea level. To get to the top, there is a cable car, and it is the only cable car in Kerala. The honor of being the largest bird sculpture in the world belongs to Jatayu.
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Munroe Island', 'Munroe Island is an inland island group located at the confluence of Ashtamudi Lake and the Kallada River, in Kollam district, Kerala, South India. It is a group of eight small islets comprising a total area of about 13.4 km2. The island, accessible by road, rail and inland water navigation, is about 25 kilometres (16 mi) from Kollam by road, 38 kilometres (24 mi) north from Paravur, 12 kilometres (7.5 mi) west from Kundara and about 25 kilometres (16 mi) from Karunagapally. As of the 2011 India', 'Tourist Attraction', 'Munroe Island, KL, India', 8.99377, 76.60998, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/5/5e/Beautiful_Munroe_Island_%2C_kollam_district_%2C_kerala.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Kallada River', 'The Kallada River is the longest river in Kollam District, Kerala, India. The river originates in Madathara, in the Western Ghats, and flows west, reaching the Arabian Sea after traveling a distance of 120 km (75 mi).', 'Tourist Attraction', 'Kallada River, West Kallada, Kunnathur, India', 8.999927265741754, 76.61558450311551, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Kallada_river_near_Uppood.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Mayyanad Beach', '', 'Beach', 'Beach, AL, India', 9.664348, 76.29445, 4.5, '', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Sasthamkotta Lake', 'Sasthamcotta Lake or Sasthamkotta Lake, also categorized as a wetland, is the largest fresh water lake in Kerala, a state of India on the south of the West Coast. The lake is named after the ancient Sastha temple (a pilgrimage centre) located on its bank. It meets the drinking water needs of half million people of the Quilon district and also provides fishing resources. The purity of the lake water for drinking use is attributed to the presence of large population of larva called cavaborus that ', 'Dam/Lake', 'Sasthamkotta Lake, Sasthamkotta - 691504, KL, India', 9.043883950000001, 76.63588468738092, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/b/b0/Sasthamcotta_Lake_By_ArunElectra.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Kulathupuzha Temple', '', 'Religious Site', 'Kulathupuzha Sastha Temple, Kulathupuzha, KL, India', 8.900954, 77.05927278139164, 4.5, '', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Achankovil Temple', '', 'Religious Site', 'Achankovil, KL, India', 9.091498, 77.123276, 4.5, '', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Shenduruny Wildlife Sanctuary', 'Shendurney Wildlife Sanctuary is a protected area in the Western Ghats, India, located in Kollam district of Kerala and comes under the control of the Agasthyamalai Biosphere Reserve. It was established on 25 August 1984 and comprises 172.403 square kilometres (66.565 sq mi). The name is a corruption of the Chengurinji, a tree endemic to the region (Gluta travancorica). Tropical evergreen and semi-evergreen forest cover a major area of the sanctuary. The sanctuary has an artificial lake of nearl', 'Wildlife', 'Idukki Wildlife Sanctuary, Idukki, India', 9.785209, 77.046129, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/5/55/VB_054_Hump-Nosed_Viper_01.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Rosemala', '', 'Tourist Attraction', 'Rosemala, KL, India', 8.9199973, 77.1754199, 4.5, '', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Aryankavu', 'Aryankavu is a village located in the Kollam district of the Indian state of Kerala. It lies close to the border between Kerala and Tamil Nadu near Thenmala. It is also one of the famous pilgrimage sites associated with the legend of Sabarimala. The village is located beside Shendurney Wildlife Sanctuary', 'Tourist Attraction', 'Aryankavu, KL, India', 8.9774094, 77.1512254, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/4/4e/Aryankavu_Station.jpg', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Ochira Temple', '', 'Religious Site', 'Ochira Railway Station Rd, MDR, Oachira - 690533, KL, India', 9.1318373, 76.5251596, 4.5, '', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Alumkadavu Boat Building Yard', '', 'Tourist Attraction', 'Yard, Itlavanipalem, AP, India', 17.894602, 83.36259498514536, 4.5, '', true);
INSERT INTO attractions (name, description, category, address, lat, lng, rating, image_url, is_verified) VALUES ('Thirumullavaram Beach', 'Thirumullavaram Beach (Malayalam: തിരുമുല്ലവാരം ബീച്ച്), is one of the popular beaches in the city of Kollam and a tourist destination in the state of Kerala. The beach is situated at Thirumullavaram, an important neighbourhood of Kollam city. The beach is very famous for conducting the Karkidaka Vavubali rituals. Thousands of devotees arrive on the beach to perform the Vavubali Tharpanam every year. It is one of the most attractive beaches located in South India.', 'Beach', 'Thirumullavaram Beach, Thirumullavaram, Kollam - 691001, KL, India', 8.8947282, 76.55368779484621, 4.5, 'https://upload.wikimedia.org/wikipedia/commons/1/16/Thirumullavaram_DTPC_Notification_board.jpg', true);